const clean=v=>String(v??'').trim(),uid=()=>`SEC-${Math.random().toString(36).slice(2,10).toUpperCase()}`, slugify=v=>clean(v).toLowerCase().replace(/&/g,' and ').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');
