$('approvedBySkId').readOnly=true;$('approvedBySkId').title='Verified staff identity from the Wix session';for(const id of ['title','documentId','slug','scope','brand','publicType','category','owner','version','effectiveDate','statusField','sortOrder','summary','reviewMode','reviewIntervalMonths','reviewDate'])$(id).addEventListener('input',e=>{const name=id==='statusField'?'status':id;p[name]=id==='sortOrder'||id==='reviewIntervalMonths'?Number(e.target.value||0):e.target.value;setDirty(true);if(id==='title'&&(!p.slug||p.slug===slugify(p._lastTitle||''))){p.slug=slugify(p.title);$('slug').value=p.slug}if(id==='title')p._lastTitle=p.title;});
