function openPolicy(id){if(current?._id===id){view='editor';render();return}attemptLeave({kind:'policy',id})}
function savePolicy(after=''){if(!current)return;if(view==='editor')syncEditor();const p=current;if(p.__controlledImportWarning){status(`Version reconciliation required: controlled source ${p.__controlledImportWarning.sourceVersion} vs observed live policy ${p.__controlledImportWarning.liveVersion}. Compare the published record before saving.`, 'error');return}if(!clean(p.title)||!clean(p.documentId)||!clean(p.effectiveDate)){status('Policy name, document ID and effective date are required.','error');view='editor';render();return}if(!(p.sections||[]).length){status('Add at least one policy section.','error');view='editor';render();return}if(busy)return;busy=true;pendingAction=after;saveIntent='save';saveRevision=editorRevision;updateButtons();refreshDocumentState();status('Saving policy to the controlled register…');post('POLICY_SAVE_REQUEST',{policy:current,changeSummary:'Saved from Policy Control V12 responsive editor.'})}
