function download(){if(!current)return;if(view==='editor')syncEditor();const doc=document.implementation.createHTMLDocument(current.title||'Policy');doc.body.innerHTML=`<h1>${esc(current.title)}</h1>${sanitize(current.introductionHtml||'')}${flatten(current.sections||[]).map(x=>`<h${Math.min(6,2+x.depth)}>${esc(x.number)} ${esc(x.s.title)}</h${Math.min(6,2+x.depth)}>${sanitize(x.s.bodyHtml)}`).join('')}`;const blob=new Blob(['<!DOCTYPE html><meta charset="utf-8"><title>Policy</title>',doc.body.innerHTML],{type:'text/html;charset=utf-8'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=(current.documentId||'policy').replace(/[^a-z0-9_-]/gi,'_')+'.html';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
