function analyzeDocument(source,fileName,hints=[]){const data=String(source||'').replace(/\r\n?/g,'\n').replace(/[\u2028\u2029]/g,'\n').replace(/\u0000/g,'').slice(0,200000);if(data.trim().length<35)throw new Error('Not enough readable document text was detected. Try OCR or a clearer source document.');const special=parseControlledMarkdown(data,fileName);if(special)return special;const meta=inferMetadata(data,fileName);const blocks=inferSections(data,hints);return{fileName,source:data,proposals:meta.proposals,sections:blocks.sections,introductionHtml:blocks.introductionHtml,warnings:[...meta.warnings,...blocks.warnings],headings:blocks.headingCount,createdAt:new Date().toISOString(),preserveSource:true};}
